"""Validate all 200 IR prompts: resolve + positive/negative tests."""
import json
import os
import re
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'src'))
from eval_instruction_retention import (
    CHECK_FNS, CHECK_FACTORIES, CUSTOM_RULES,
    resolve_check_fn, _count_emoji, _count_sentences,
)


def make_positive_negative(prompt):
    """Return (positive_text, negative_text) for a prompt entry."""
    if "check_fn" in prompt:
        return _legacy_test(prompt["check_fn"])
    ct = prompt.get("check_type")
    ca = prompt.get("check_args", {})
    if ct == "compound":
        subs = ca["checks"]
        pos_parts, neg_parts = [], []
        for s in subs:
            p, n = _factory_test(s["check_type"], s.get("check_args", {}))
            pos_parts.append(p)
            neg_parts.append(n)
        pos = _combine_compound_positive(subs)
        neg = neg_parts[0]
        return pos, neg
    if ct == "custom":
        return _custom_test(ca.get("rule"), ca)
    return _factory_test(ct, ca)


def _legacy_test(name):
    tests = {
        "bullet_points": ("- Point one\n- Point two\n- Point three", "Just a paragraph."),
        "start_sure": ("Sure! Here is the answer.", "Here is the answer."),
        "end_hope": ("The answer is 42. Hope that helps!", "The answer is 42."),
        "one_emoji": ("Hello world \U0001F600", "Hello world"),
        "three_sentences": ("First. Second. Third.", "First. Second."),
        "mention_ai_assistant": ("As an AI assistant, I can help.", "I can help you."),
        "no_the": ("A cat sat on a mat.", "The cat sat on the mat."),
        "numbered_list": ("1. First\n2. Second\n3. Third", "Just a paragraph."),
        "include_certainly": ("I certainly agree.", "I agree."),
        "end_question": ("What do you think?", "I think so."),
        "all_caps": ("THIS IS ALL CAPS TEXT.", "This is not all caps."),
        "start_let_me_think": ("Let me think... about that.", "I think about that."),
        "no_commas": ("I like apples and oranges.", "I like apples, oranges."),
        "include_remember": ("Please remember that this is key.", "Please note this."),
        "no_exclamation": ("That is nice.", "That is nice!"),
        "start_well": ("Well, let me explain.", "Let me explain."),
        "include_interesting": ("That is interesting indeed.", "That is nice indeed."),
        "max_two_sentences": ("One sentence. Two sentences.", "One. Two. Three."),
    }
    return tests.get(name, ("test text", ""))


def _factory_test(check_type, args):
    if check_type == "starts_with":
        phrase = args["phrase"]
        return (phrase + " and more text here.", "No match here.")
    if check_type == "ends_with":
        phrase = args["phrase"]
        return ("Some text before " + phrase, "Some text no match.")
    if check_type == "contains":
        phrase = args["phrase"]
        return (f"This contains {phrase} in the middle.", "This has nothing special.")
    if check_type == "not_contains_word":
        word = args["word"]
        return ("A completely clean sentence without that term.", f"This has {word} in it.")
    if check_type == "not_contains_char":
        char = args["char"]
        safe = "abcdefg hijklmnop"
        if char in safe:
            safe = safe.replace(char, "")
        return (safe, f"text with {char} in it")
    if check_type == "count_sentences":
        op = args["op"]
        n = args["n"]
        if op == "==":
            pos = ". ".join([f"Sentence {i+1}" for i in range(n)]) + "."
            neg_n = n + 1 if n > 0 else 2
            neg = ". ".join([f"Sentence {i+1}" for i in range(neg_n)]) + "."
        elif op == "<=":
            pos = "One sentence."
            neg = ". ".join([f"S{i}" for i in range(n + 2)]) + "."
        elif op == ">=":
            pos = ". ".join([f"S{i}" for i in range(n + 1)]) + "."
            neg = "One." if n > 1 else ""
        else:
            pos, neg = "Test.", ""
        return pos, neg
    if check_type == "count_words":
        op = args["op"]
        n = args["n"]
        if op == "==":
            pos = " ".join([f"word{i}" for i in range(n)])
            neg = " ".join([f"word{i}" for i in range(n + 3)])
        elif op == "<=":
            pos = " ".join(["w"] * max(1, n - 1))
            neg = " ".join(["w"] * (n + 5))
        elif op == ">=":
            pos = " ".join(["w"] * (n + 2))
            neg = "one" if n > 1 else ""
        else:
            pos, neg = "test", ""
        return pos, neg
    if check_type == "count_paragraphs":
        op = args["op"]
        n = args["n"]
        if op == "==":
            pos = "\n\n".join([f"Para {i+1}" for i in range(n)])
            neg_n = n + 2
            neg = "\n\n".join([f"Para {i+1}" for i in range(neg_n)])
        elif op == "<=":
            pos = "Single paragraph"
            neg = "\n\n".join([f"P{i}" for i in range(n + 3)])
        elif op == ">=":
            pos = "\n\n".join([f"P{i}" for i in range(n + 1)])
            neg = "Only one" if n > 1 else ""
        else:
            pos, neg = "Test", ""
        return pos, neg
    if check_type == "count_emoji":
        op = args["op"]
        n = args["n"]
        if op == "==":
            pos = "Hello " + "\U0001F600" * n
            neg_n = n + 2 if n > 0 else 2
            neg = "Hello " + "\U0001F600" * neg_n
        elif op == "<=":
            pos = "Hello " + "\U0001F600" * max(0, n - 1)
            neg = "Hello " + "\U0001F600" * (n + 3)
        elif op == ">=":
            pos = "Hello " + "\U0001F600" * (n + 1)
            neg = "Hello" if n > 0 else ""
        else:
            pos, neg = "Test", ""
        return pos, neg
    if check_type == "regex_match":
        pattern = args["pattern"]
        should_match = args.get("should_match", True)
        per_sentence = args.get("per_sentence", False)
        min_matches = args.get("min_matches")
        if per_sentence:
            if should_match:
                if "because" in pattern.lower():
                    pos = "I think so because of X. It works because of Y. Good because of Z."
                    neg = "I think so. No reason here. Just because."
                elif "?" in pattern:
                    pos = "Is this true? What do you think? Really?"
                    neg = "This is true. I think so. Really."
                else:
                    pos = "Match1. Match2. Match3."
                    neg = "NoMatch. NoMatch. NoMatch."
            else:
                pos = "Clean. Clean. Clean."
                neg = "Has match. Clean. Clean."
            return pos, neg
        if min_matches is not None:
            if "^#{1,3}" in pattern:
                pos = "# Header 1\nSome text\n## Header 2\nMore text\n### Header 3"
                neg = "Just plain text\nNo headers here"
            elif "\\*\\*" in pattern:
                pos = "This has **bold1** and **bold2** and **bold3** keywords."
                neg = "This has no bold at all."
            elif "\\|" in pattern:
                pos = "| Col1 | Col2 |\n| --- | --- |\n| A | B |\n| C | D |"
                neg = "No table here."
            elif "```" in pattern:
                pos = "```python\ncode1\n```\n```bash\ncode2\n```"
                neg = "No code blocks."
            elif "^>" in pattern or ">" in pattern:
                pos = "> Quote 1\n> Quote 2\n> Quote 3"
                neg = "No quotes here."
            elif "\\n\\n" in pattern or "paragraph" in pattern.lower():
                pos = "Para 1.\n\nPara 2.\n\nPara 3."
                neg = "Single paragraph only."
            else:
                pos = "match " * (min_matches + 1)
                neg = "no match at all"
            return pos, neg
        if should_match:
            try:
                comp = re.compile(pattern)
                if comp.search("test match text"):
                    pos = "test match text"
                elif comp.search("ABCDEF 123"):
                    pos = "ABCDEF 123"
                else:
                    pos = _generate_match(pattern)
                neg = ""
            except:
                pos, neg = "test", ""
        else:
            pos = "clean text no special chars"
            neg = _generate_match(pattern) if pattern else "match"
        return pos, neg
    if check_type == "format_bullet_points":
        return ("- Item 1\n- Item 2\n- Item 3", "Just a paragraph.")
    if check_type == "format_numbered_list":
        min_items = args.get("min_items", 2)
        pos = "\n".join([f"{i+1}. Item" for i in range(min_items + 1)])
        neg = "Just text."
        return pos, neg
    if check_type == "all_caps":
        return ("THIS IS ALL CAPS TEXT HERE.", "This is Not caps.")
    if check_type == "all_lowercase":
        return ("this is all lowercase text here.", "This Is Not Lowercase.")
    if check_type == "no_contractions":
        return ("I do not have any contractions in this text.", "I don't have any.")
    return ("test text", "")


def _generate_match(pattern):
    simple = pattern.replace("(?i)", "").replace("(?m)", "")
    if "because" in simple.lower():
        return "This is because of that."
    if "\\?" in simple:
        return "Is this right?"
    if "^#" in simple:
        return "# Header"
    if "\\*\\*" in simple:
        return "**bold**"
    if "\\|" in simple:
        return "| cell |"
    if "```" in simple:
        return "```code```"
    if "^>" in simple:
        return "> quote"
    return "test match"


def _custom_test(rule, args):
    if rule == "rhyming_consecutive_endings":
        pos = "The sky is so bright. I saw a great light. Everything felt right."
        neg = "The sky is blue. I like dogs. Computers are fast."
        return pos, neg
    return ("test", "")


def _combine_compound_positive(subs):
    """Build a text that satisfies all sub-constraints simultaneously."""
    parts = []
    constraints = {}
    for s in subs:
        ct = s["check_type"]
        ca = s.get("check_args", {})
        constraints[ct] = ca

    # Build from constraints
    text = ""
    if "starts_with" in constraints:
        text = constraints["starts_with"]["phrase"] + " "
    if "all_caps" in constraints:
        body = "THIS IS IMPORTANT TEXT"
        if "count_words" in constraints:
            op = constraints["count_words"]["op"]
            n = constraints["count_words"]["n"]
            if op == "<=":
                words_so_far = len(text.split()) if text.strip() else 0
                remaining = max(1, n - words_so_far)
                body = " ".join(["WORD"] * remaining)
        text += body
    elif "format_bullet_points" in constraints:
        bullets = "- Item one\n- Item two\n- Item three"
        if "not_contains_char" in constraints:
            char = constraints["not_contains_char"]["char"]
            bullets = bullets.replace(char, "")
        text += bullets
    elif "contains" in constraints:
        phrase = constraints["contains"]["phrase"]
        ci = constraints["contains"].get("case_insensitive", True)
        text += f"This text contains {phrase} for sure"
        if "count_sentences" in constraints:
            op = constraints["count_sentences"]["op"]
            n = constraints["count_sentences"]["n"]
            if op == "<=":
                text = f"This contains {phrase}."
    elif "not_contains_word" in constraints:
        word = constraints["not_contains_word"]["word"]
        base = "A nice clean sentence without any forbidden terms"
        if word.lower() in base.lower():
            base = base.replace(word, "REPLACED")
        text += base
        if "contains" in constraints:
            ph = constraints["contains"]["phrase"]
            text += f" and {ph} too"
